import React from "react";
import { Card, Row, Col } from "react-bootstrap";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faUsers,
  faUserShield,
  faUserCheck,
  faClock,
  faExchangeAlt,
  faTags,
} from "@fortawesome/free-solid-svg-icons";
import Loader from "components/ui/loader/Loader";

import "./adminStyles.css";
import { useGetUserStatsQuery } from "services/api/adminApi";

const StatCard = ({ icon, title, value, color, subtitle, dataCy }) => (
  <Col md={6} lg={4} className="mb-4">
    <Card className="stats-card" data-cy={dataCy}>
      <Card.Body className="d-flex align-items-center p-0 m-0 px-2">
        <div
          className={`stats-icon rounded-circle d-flex align-items-center justify-content-center me-3 bg-${color}`}
        >
          {icon}
        </div>
        <div className="flex-grow-1">
          <h3 className="stats-value mb-1">{value}</h3>
          <p className="stats-title mb-0 text-muted">{title}</p>
          {subtitle && <small className="text-muted">{subtitle}</small>}
        </div>
      </Card.Body>
    </Card>
  </Col>
);

const AdminStats = () => {
  const { data: stats, isLoading, error } = useGetUserStatsQuery();

  if (isLoading) return <Loader data-cy="loading-spinner" />;
  if (error)
    return (
      <div className="alert alert-danger" data-cy="error-message">
        Error loading statistics
      </div>
    );

  return (
    <div className="admin-stats" data-cy="admin-stats">
      <Row>
        <StatCard
          icon={<FontAwesomeIcon icon={faUsers} size="lg" />}
          title="Total Users"
          value={stats?.totalUsers || 0}
          color="primary"
          dataCy="total-users-card"
        />
        <StatCard
          icon={<FontAwesomeIcon icon={faUserShield} size="lg" />}
          title="Admin Users"
          value={stats?.adminUsers || 0}
          color="warning"
          dataCy="admin-users-card"
        />
        <StatCard
          icon={<FontAwesomeIcon icon={faUserCheck} size="lg" />}
          title="Regular Users"
          value={stats?.regularUsers || 0}
          color="success"
          dataCy="regular-users-card"
        />
        <StatCard
          icon={<FontAwesomeIcon icon={faClock} size="lg" />}
          title="New Users"
          value={stats?.recentUsers || 0}
          color="info"
          subtitle="Last 30 days"
          dataCy="recent-users-card"
        />
        <StatCard
          icon={<FontAwesomeIcon icon={faExchangeAlt} size="lg" />}
          title="Total Transactions"
          value={stats?.totalTransactions || 0}
          color="secondary"
          dataCy="total-transactions-card"
        />
        <StatCard
          icon={<FontAwesomeIcon icon={faTags} size="lg" />}
          title="Total Categories"
          value={stats?.totalCategories || 0}
          color="dark"
          dataCy="total-categories-card"
        />
      </Row>
    </div>
  );
};

export default AdminStats;
